// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title TokenVesting
 * @notice Linear vesting with cliff, supports schedule modifications by admin
 * @dev Implements adjustable vesting with proper overflow protection
 */
contract TokenVesting is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    struct VestingSchedule {
        address beneficiary;
        address token;
        uint256 totalAmount;
        uint256 released;
        uint256 startTime;
        uint256 cliffDuration;
        uint256 vestingDuration;
        bool revoked;
        int256 timeAdjustment; // admin can shift schedule forward/backward
    }

    mapping(bytes32 => VestingSchedule) private _schedules;
    mapping(address => uint256) private _beneficiaryCount;
    uint256 private _scheduleCount;

    event ScheduleCreated(bytes32 indexed scheduleId, address indexed beneficiary);
    event TokensReleased(bytes32 indexed scheduleId, uint256 amount);
    event ScheduleRevoked(bytes32 indexed scheduleId);
    event TimeAdjusted(bytes32 indexed scheduleId, int256 adjustment);

    constructor() Ownable() {}

    function createSchedule(
        address beneficiary,
        address token,
        uint256 totalAmount,
        uint256 startTime,
        uint256 cliffDuration,
        uint256 vestingDuration
    ) external onlyOwner returns (bytes32) {
        require(beneficiary != address(0), "Invalid beneficiary");
        require(token != address(0), "Invalid token");
        require(totalAmount > 0, "Amount must be > 0");
        require(vestingDuration > 0, "Duration must be > 0");
        require(vestingDuration > cliffDuration, "Vesting must exceed cliff");

        bytes32 scheduleId = keccak256(
            abi.encodePacked(beneficiary, token, _scheduleCount)
        );
        _scheduleCount++;

        _schedules[scheduleId] = VestingSchedule({
            beneficiary: beneficiary,
            token: token,
            totalAmount: totalAmount,
            released: 0,
            startTime: startTime,
            cliffDuration: cliffDuration,
            vestingDuration: vestingDuration,
            revoked: false,
            timeAdjustment: 0
        });

        _beneficiaryCount[beneficiary]++;

        IERC20(token).safeTransferFrom(msg.sender, address(this), totalAmount);

        emit ScheduleCreated(scheduleId, beneficiary);
        return scheduleId;
    }

    /**
     * @notice Admin can adjust the vesting timeline forward or backward
     * @param scheduleId The schedule to adjust
     * @param adjustment Positive = delay vesting, Negative = accelerate vesting
     */
    function adjustTimeline(
        bytes32 scheduleId,
        int256 adjustment
    ) external onlyOwner {
        VestingSchedule storage schedule = _schedules[scheduleId];
        require(schedule.beneficiary != address(0), "Schedule not found");
        require(!schedule.revoked, "Schedule revoked");

        // Ensure adjustment doesn't push effective start before epoch 0
        // or create unreasonable delays
        require(adjustment > -int256(schedule.startTime), "Would underflow start");
        require(adjustment < 365 days * 10, "Adjustment too large");

        // Bound cumulative adjustment to prevent manipulation
        int256 newAdjustment = schedule.timeAdjustment + adjustment;
        require(newAdjustment >= -int256(schedule.vestingDuration), "Cumulative adjustment too negative");
        require(newAdjustment <= int256(schedule.vestingDuration * 2), "Cumulative adjustment too positive");

        schedule.timeAdjustment = newAdjustment;
        emit TimeAdjusted(scheduleId, adjustment);
    }

    function release(bytes32 scheduleId) external nonReentrant {
        VestingSchedule storage schedule = _schedules[scheduleId];
        require(msg.sender == schedule.beneficiary, "Not beneficiary");
        require(!schedule.revoked, "Schedule revoked");

        uint256 vested = _computeVestedAmount(schedule);
        uint256 releasable = vested - schedule.released;
        require(releasable > 0, "Nothing to release");

        schedule.released += releasable;
        IERC20(schedule.token).safeTransfer(schedule.beneficiary, releasable);

        emit TokensReleased(scheduleId, releasable);
    }

    function revoke(bytes32 scheduleId) external onlyOwner nonReentrant {
        VestingSchedule storage schedule = _schedules[scheduleId];
        require(schedule.beneficiary != address(0), "Schedule not found");
        require(!schedule.revoked, "Already revoked");

        uint256 vested = _computeVestedAmount(schedule);
        uint256 unreleased = vested - schedule.released;
        uint256 refund = schedule.totalAmount - vested;

        schedule.revoked = true;

        if (unreleased > 0) {
            schedule.released += unreleased;
            IERC20(schedule.token).safeTransfer(schedule.beneficiary, unreleased);
        }
        if (refund > 0) {
            IERC20(schedule.token).safeTransfer(owner(), refund);
        }

        emit ScheduleRevoked(scheduleId);
    }

    function getVestedAmount(bytes32 scheduleId) external view returns (uint256) {
        return _computeVestedAmount(_schedules[scheduleId]);
    }

    function getReleasable(bytes32 scheduleId) external view returns (uint256) {
        VestingSchedule storage schedule = _schedules[scheduleId];
        return _computeVestedAmount(schedule) - schedule.released;
    }

    function getSchedule(bytes32 scheduleId) external view returns (
        address beneficiary,
        address token,
        uint256 totalAmount,
        uint256 released,
        uint256 startTime,
        uint256 cliffDuration,
        uint256 vestingDuration,
        bool revoked,
        int256 timeAdjustment
    ) {
        VestingSchedule storage s = _schedules[scheduleId];
        return (s.beneficiary, s.token, s.totalAmount, s.released,
                s.startTime, s.cliffDuration, s.vestingDuration,
                s.revoked, s.timeAdjustment);
    }

    /**
     * @dev Core vesting calculation with timeline adjustment
     * The effective elapsed time accounts for the admin's time adjustment.
     * A positive adjustment delays vesting (as if less time has passed).
     */
    function _computeVestedAmount(
        VestingSchedule storage schedule
    ) internal view returns (uint256) {
        if (block.timestamp < schedule.startTime) {
            return 0;
        }

        // Calculate base elapsed time
        uint256 baseElapsed = block.timestamp - schedule.startTime;

        // Apply time adjustment: positive delays, negative accelerates
        // effectiveElapsed represents how far along the vesting we are
        int256 adjustedElapsed = int256(baseElapsed) + schedule.timeAdjustment;

        // If adjustment pushes us before start, nothing vested
        if (adjustedElapsed <= 0) {
            return 0;
        }

        uint256 effectiveElapsed = uint256(adjustedElapsed);

        // Check cliff
        if (effectiveElapsed < schedule.cliffDuration) {
            return 0;
        }

        // Calculate vested amount - cap at total
        if (effectiveElapsed >= schedule.vestingDuration) {
            return schedule.totalAmount;
        }

        return (schedule.totalAmount * effectiveElapsed) / schedule.vestingDuration;
    }
}
